const leads = $('Отримання даних про лідів')
  .all()
  .map(item => item.json);

const analyses = $('Отримання аналізу дзвінків')
  .all()
  .map(item => item.json);

const normalize = (value) =>
  String(value ?? '').trim().toLowerCase();

const toNumber = (value) => {
  const number = Number(String(value ?? '').replace(',', '.'));
  return Number.isFinite(number) ? number : null;
};

const isTrue = (value) =>
  value === true || normalize(value) === 'true';

const uniqueNonEmpty = (values) =>
  [...new Set(values.map(String).map(v => v.trim()).filter(Boolean))];

const completedCalls = leads.filter(
  lead => normalize(lead.call_status) === 'done'
);

const analyzedCalls = analyses.filter(
  call => normalize(call.analysis_status) === 'analyzed'
);

const scores = analyzedCalls
  .map(call => toNumber(call.ai_score))
  .filter(score => score !== null);

const successfulCalls = analyzedCalls.filter(
  call => normalize(call.result) === 'успішно'
).length;

const partialCalls = analyzedCalls.filter(
  call => normalize(call.result) === 'частково'
).length;

const unsuccessfulCalls = analyzedCalls.filter(
  call => normalize(call.result) === 'неуспішно'
).length;

const hotLeads = analyzedCalls.filter(
  call => normalize(call.lead_temperature) === 'hot'
).length;

const warmLeads = analyzedCalls.filter(
  call => normalize(call.lead_temperature) === 'warm'
).length;

const coldLeads = analyzedCalls.filter(
  call => normalize(call.lead_temperature) === 'cold'
).length;

const averageScore = scores.length
  ? Math.round(scores.reduce((sum, score) => sum + score, 0) / scores.length)
  : 0;

const conversionRate = analyzedCalls.length
  ? Math.round((successfulCalls / analyzedCalls.length) * 100)
  : 0;

return [
  {
    json: {
      report_date: new Date().toISOString(),

      total_leads: leads.length,
      completed_calls: completedCalls.length,
      analyzed_calls: analyzedCalls.length,

      successful_calls: successfulCalls,
      partial_calls: partialCalls,
      unsuccessful_calls: unsuccessfulCalls,

      average_ai_score: averageScore,
      conversion_rate: conversionRate,

      hot_leads: hotLeads,
      warm_leads: warmLeads,
      cold_leads: coldLeads,

      human_handoffs: leads.filter(
        lead => isTrue(lead.human_handoff)
      ).length,

      customer_objections: uniqueNonEmpty(
        analyzedCalls.map(call => call.customer_objections)
      ),

      agent_errors: uniqueNonEmpty(
        analyzedCalls.map(call => call.agent_errors)
      ),

      successful_patterns: uniqueNonEmpty(
        analyzedCalls.map(call => call.successful_pattern)
      ),

      recommended_next_steps: uniqueNonEmpty(
        analyzedCalls.map(call => call.next_step)
      ),

      missing_duration_count: analyzedCalls.filter(
        call => !call.duration_seconds
      ).length
    }
  }
];

