const report = $json.output;
const metrics = $('Розрахунок CEO-метрик').first().json;

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const shorten = (value, maxLength = 280) => {
  const text = String(value ?? '').trim();

  if (text.length <= maxLength) {
    return escapeHtml(text);
  }

  return `${escapeHtml(text.slice(0, maxLength))}…`;
};

const list = (items, limit = 2) => {
  if (!Array.isArray(items) || items.length === 0) {
    return '• Немає суттєвих';
  }

  return items
    .slice(0, limit)
    .map(item => `• ${shorten(item, 220)}`)
    .join('\n');
};

const statuses = {
  Green: {
    icon: '🟢',
    label: 'Стабільно'
  },
  Yellow: {
    icon: '🟡',
    label: 'Потрібна увага'
  },
  Red: {
    icon: '🔴',
    label: 'Критично'
  }
};

const status = statuses[report.overall_status] || {
  icon: '⚪',
  label: 'Немає оцінки'
};

const reportDate = String(
  metrics.period_end ||
  metrics.report_date ||
  new Date().toISOString()
).slice(0, 10);

const message = [
  `<b>📊 CEO-звіт | ${reportDate}</b>`,
  `${status.icon} <b>${status.label}</b>`,
  '',
  `📈 Ліди: <b>${metrics.total_leads}</b> | Дзвінки: <b>${metrics.analyzed_calls}</b> | Конверсія: <b>${metrics.conversion_rate}%</b>`,
  `🎯 AI Score: <b>${metrics.average_ai_score}</b> | Hot: <b>${metrics.hot_leads}</b> | Успішні: <b>${metrics.successful_calls}/${metrics.analyzed_calls}</b>`,
  '',
  '<b>Короткий висновок</b>',
  shorten(report.executive_summary, 350),
  '',
  '<b>Основні ризики</b>',
  list(report.risks, 2),
  '',
  '<b>Наступні дії</b>',
  list(report.recommendations, 2),
  '',
  '<b>Головний пріоритет</b>',
  `🎯 ${shorten(report.priority_action, 250)}`
].join('\n');

return [
  {
    json: {
      message
    }
  }
];
